<?php
require __DIR__.'/../bootstrap.php'; require_admin(); ensure_cms_schema();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=(string)post('action');$id=(int)post('id');$ids=array_values(array_filter(array_map('intval',(array)post('ids',[]))));if($action==='bulk'&&$id)$action='approved';if($action==='reply'&&$id){$parent=db()->prepare('SELECT * FROM cms_comments WHERE id=? LIMIT 1');$parent->execute([$id]);$pc=$parent->fetch();$reply=trim((string)post('reply_content',''));if($pc&&$reply!==''){db()->prepare("INSERT INTO cms_comments(post_id,parent_id,author_name,author_email,content,status,created_at,updated_at) VALUES(?,?,?,?,?,'approved',NOW(),NOW())")->execute([(int)$pc['post_id'],$id,current_user()['full_name']?:'PocketCat Admin',current_user()['email']??null,$reply]);flash('success','Reply published.');}else{flash('error','Reply text is required.');}redirect('/admin/comments/?status='.urlencode($status??'pending'));}elseif($action==='bulk'&&$ids){$st=(string)post('status','approved');if(!in_array($st,['approved','pending','spam','trash'],true))$st='pending';$in=implode(',',array_fill(0,count($ids),'?'));db()->prepare("UPDATE cms_comments SET status=?,updated_at=NOW() WHERE id IN ($in)")->execute(array_merge([$st],$ids));}elseif($id&&in_array($action,['approved','pending','spam','trash'],true)){db()->prepare('UPDATE cms_comments SET status=?,updated_at=NOW() WHERE id=?')->execute([$action,$id]);}flash('success','Comment moderation updated.');redirect('/admin/comments/');}
$postFilter=(int)getv('post',0);$status=(string)getv('status','pending');$allowed=['pending','approved','spam','trash'];if(!in_array($status,$allowed,true))$status='pending';$sql="SELECT c.*,p.title post_title FROM cms_comments c INNER JOIN cms_posts p ON p.id=c.post_id WHERE c.status=?";$params=[$status];if($postFilter>0){$sql.=' AND c.post_id=?';$params[]=$postFilter;}$sql.=' ORDER BY c.created_at DESC';$st=db()->prepare($sql);$st->execute($params);$rows=$st->fetchAll();$counts=[];foreach($allowed as $x){$q=db()->prepare('SELECT COUNT(*) FROM cms_comments WHERE status=?');$q->execute([$x]);$counts[$x]=(int)$q->fetchColumn();}$title='Comments · CMS';require __DIR__.'/../includes/header.php';
?><div class="page-head"><div><span class="eyebrow">Content Management</span><h1>Comments</h1><p>Moderate discussion from one admin queue.</p></div><?php if($postFilter):?><a class="btn secondary" href="/admin/comments/">Show all comments</a><?php endif;?></div><div class="card cms-toolbar"><div class="cms-filters"><?php foreach($allowed as $x):?><a class="pill <?=($x===$status?'active':'')?>" href="?status=<?=$x?>"><?=ucfirst($x)?> <strong><?=$counts[$x]?></strong></a><?php endforeach;?></div></div><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="bulk"><div class="card table-wrap"><div class="bulkbar"><label class="check"><input type="checkbox" data-check-all="#commentBulk input[name='ids[]']"> Select all</label><select name="status"><option value="approved">Approve</option><option value="pending">Pending</option><option value="spam">Spam</option><option value="trash">Trash</option></select><button class="btn" type="submit">Apply</button></div><div id="commentBulk"><table class="cms-table"><thead><tr><th></th><th>Author</th><th>Comment</th><th>Post</th><th>Date</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><input type="checkbox" name="ids[]" value="<?=$r['id']?>"></td><td><strong><?=e($r['author_name'])?></strong><br><small><?=e($r['author_email']??'')?></small></td><td><?=e(mb_strimwidth($r['content'],0,240,'…'))?><?php if(!empty($r['parent_id'])):?><div><small class="muted">↳ Reply to comment #<?=((int)$r['parent_id'])?></small></div><?php endif;?><div class="row-actions"><button name="id" value="<?=$r['id']?>" formaction="/admin/comments/" formmethod="post" type="submit">Approve</button><button type="button" data-comment-reply="<?=$r['id']?>">Reply</button></div></td><td><?=e($r['post_title'])?></td><td><?=e(date('M j, Y H:i',strtotime($r['created_at'])))?></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="5">No comments in this queue.</td></tr><?php endif;?></tbody></table></div></div></form><script>document.querySelectorAll('[data-comment-reply]').forEach(b=>b.addEventListener('click',async()=>{const text=prompt('Write an admin reply:');if(!text||!text.trim())return;const csrf=document.querySelector('input[name=csrf]')?.value||'';const fd=new URLSearchParams({csrf,action:'reply',id:b.dataset.commentReply,reply_content:text.trim()});try{const r=await fetch('/admin/comments/',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:fd});if(r.ok)location.reload();else alert('Could not publish reply.');}catch(e){alert('Network error while publishing reply.');}}));</script><?php require __DIR__.'/../includes/footer.php'; ?>
